/**
 * Colour maths for themes: sRGB <-> OKLab, OKLab mixing, WCAG 2 contrast.
 * Mirrors osp_spec/theme.py line for line, so a derived palette is the same hex in Python
 * (where the contrast guard runs) and here (where the page is drawn). A golden file
 * generated by Python proves it (theme-bridge.test.ts).
 */
import type { HexColour, Palette } from './types';

type Triple = [number, number, number];

const toLinear = (c: number) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const fromLinear = (c: number) => (c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055);

export function hexToRgb(hex: HexColour): Triple {
	const h = hex.replace(/^#/, '');
	return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255) as Triple;
}

export function rgbToHex(rgb: Triple): HexColour {
	return (
		'#' +
		rgb
			.map((c) =>
				Math.floor(Math.min(1, Math.max(0, c)) * 255 + 0.5)
					.toString(16)
					.padStart(2, '0')
			)
			.join('')
	);
}

export function relativeLuminance(hex: HexColour): number {
	const [r, g, b] = hexToRgb(hex).map(toLinear);
	return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

export function contrastRatio(a: HexColour, b: HexColour): number {
	const la = relativeLuminance(a);
	const lb = relativeLuminance(b);
	return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

function rgbToOklab(rgb: Triple): Triple {
	const [r, g, b] = rgb.map(toLinear);
	const lc = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
	const mc = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
	const sc = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
	return [
		0.2104542553 * lc + 0.793617785 * mc - 0.0040720468 * sc,
		1.9779984951 * lc - 2.428592205 * mc + 0.4505937099 * sc,
		0.0259040371 * lc + 0.7827717662 * mc - 0.808675766 * sc
	];
}

function oklabToHex([L, a, b]: Triple): HexColour {
	const lc = L + 0.3963377774 * a + 0.2158037573 * b;
	const mc = L - 0.1055613458 * a - 0.0638541728 * b;
	const sc = L - 0.0894841775 * a - 1.291485548 * b;
	const [l3, m3, s3] = [lc ** 3, mc ** 3, sc ** 3];
	return rgbToHex(
		[
			4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3,
			-1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3,
			-0.0041960863 * l3 - 0.7034186147 * m3 + 1.707614701 * s3
		].map(fromLinear) as Triple
	);
}

/** Interpolate from `a` towards `b` by `amount` (0..1) in OKLab, rounded to 8-bit sRGB. */
export function mix(a: HexColour, b: HexColour, amount: number): HexColour {
	const la = rgbToOklab(hexToRgb(a));
	const lb = rgbToOklab(hexToRgb(b));
	return oklabToHex(la.map((x, i) => x + (lb[i] - x) * amount) as Triple);
}

/** W1 colour token names (`--color-<name>`) a theme sets. */
export const DERIVED_TOKENS = [
	'bg',
	'surface',
	'surface-raised',
	'surface-sunken',
	'border',
	'border-strong',
	'text',
	'text-muted',
	'accent',
	'accent-hover',
	'on-accent',
	'accent-subtle',
	'selected',
	'focus',
	'danger'
] as const;
export type DerivedToken = (typeof DERIVED_TOKENS)[number];

/** The page's colour tokens for one mode, derived from the seven theme colours
 *  (same rules as osp_spec.theme.DERIVATION). */
export function derivePalette(p: Palette): Record<DerivedToken, HexColour> {
	const lower = (h: string) => h.toLowerCase();
	return {
		bg: lower(p.background),
		surface: lower(p.surface),
		'surface-raised': lower(p.background),
		'surface-sunken': mix(p.background, p.text, 0.08),
		border: mix(p.background, p.text, 0.18),
		'border-strong': lower(p.muted),
		text: lower(p.text),
		'text-muted': lower(p.muted),
		accent: lower(p.accent),
		'accent-hover': mix(p.accent, p.text, 0.15),
		'on-accent': lower(p.background),
		'accent-subtle': mix(p.background, p.accent, 0.1),
		selected: mix(p.background, p.accent, 0.18),
		focus: lower(p.focus),
		danger: lower(p.error)
	};
}
